def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    The text is passed in as a string; this function never reads files.
    Returns an empty string when the key is absent.
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_config_value_returns_matching_value() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_config_value_returns_first_line_value() -> None:
    assert config_value("host=localhost\nport=8080", "host") == "localhost"


def test_config_value_missing_key_returns_empty_string() -> None:
    assert config_value("host=localhost", "port") == ""


def test_config_value_empty_text_returns_empty_string() -> None:
    assert config_value("", "host") == ""


def test_config_value_keeps_equals_signs_in_value() -> None:
    assert config_value("expr=a=b", "expr") == "a=b"


def test_config_value_does_not_match_key_prefix() -> None:
    assert config_value("portal=1", "port") == ""
